import { ProjectRepository } from '../../domain/project/ProjectRepository';
import { DueDate } from '../../domain/task/DueDate';
import { Task } from '../../domain/task/Task';
import { TaskRepository } from '../../domain/task/TaskRepository';
import { parseTaskStatus } from '../../domain/task/TaskStatus';
import { TaskDto, toTaskDto } from '../dto/TaskDto';
import { IdGenerator } from '../ports/IdGenerator';
import { requireFound } from '../shared/requireFound';
import { AddTaskInput, AddTaskUseCase } from './AddTaskUseCase';

export class AddTaskService implements AddTaskUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: AddTaskInput): Promise<TaskDto> {
    const project = await requireFound(this.projects.findById(input.projectId), 'Project', input.projectId);
    const task = Task.create({
      id: this.ids.next(),
      projectId: project.id,
      title: input.title,
      description: input.description,
      dueDate: input.dueDate === undefined ? undefined : DueDate.fromIsoString(input.dueDate),
      status: input.status === undefined ? 'todo' : parseTaskStatus(input.status),
    });
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

=====SOURCE-END=====

