import { TaskRepository } from '../../domain/task/TaskRepository';
import { UserRepository } from '../../domain/user/UserRepository';
import { TaskDto, toTaskDto } from '../dto/TaskDto';
import { requireFound } from '../shared/requireFound';
import { AssignTaskInput, AssignTaskUseCase } from './AssignTaskUseCase';

export class AssignTaskService implements AssignTaskUseCase {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
  ) {}

  async execute(input: AssignTaskInput): Promise<TaskDto> {
    const task = await requireFound(this.tasks.findById(input.taskId), 'Task', input.taskId);
    const assignee = await requireFound(this.users.findById(input.userId), 'User', input.userId);
    task.assignTo(assignee.id);
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

