import { ProjectRepository } from '../../domain/project/ProjectRepository';
import { TaskCriteria } from '../../domain/task/TaskCriteria';
import { TaskRepository } from '../../domain/task/TaskRepository';
import { parseTaskStatus } from '../../domain/task/TaskStatus';
import { TaskDto, toTaskDto } from '../dto/TaskDto';
import { requireFound } from '../shared/requireFound';
import { ListTasksInput, ListTasksUseCase } from './ListTasksUseCase';

export class ListTasksService implements ListTasksUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: ListTasksInput): Promise<TaskDto[]> {
    const project = await requireFound(this.projects.findById(input.projectId), 'Project', input.projectId);
    const criteria = new TaskCriteria(
      project.id,
      input.status === undefined ? undefined : parseTaskStatus(input.status),
      input.assigneeId,
    );
    const tasks = await this.tasks.findMatching(criteria);
    return tasks.map(toTaskDto);
  }
}

